const fastify = require('fastify')({ logger: true })

// Register the plugin
fastify.register(require('@ananay-nag/fastify-socket-io'), {
  cors: {
    origin: '*',
    credentials: true
  },
  // This function is called immediately upon a successful connection
  connectionHandler (socket) {
    fastify.log.info(`Client connected: ${socket.id}`)

    socket.on('disconnect', () => {
      fastify.log.info(`Client disconnected: ${socket.id}`)
    })
  }
})

// Start the server
fastify.listen({ port: 3000 })

fastify.register(require('@fastify/jwt'), { secret: 'super-secure-secret' })

fastify.register(require('@ananay-nag/fastify-socket-io'), {
  jwtAuth: true, // Enables the automated security hook
  connectionHandler (socket) {
    // The payload is already verified and decoded for you!
    const userId = socket.data.user.id;
    fastify.log.info(`Authenticated User ID ${userId} connected.`);
  }
})

fastify.register(require('@ananay-nag/fastify-socket-io'), {
  // Setting this to true enables optimal default recovery settings
  connectionStateRecovery: {
    maxDisconnectionDuration: 2 * 60 * 1000, // 2 minutes
    skipMiddlewares: true // Skip middlewares upon successful recovery
  }
})

import Fastify from 'fastify'
import fastifySocketIO from '@ananay-nag/fastify-socket-io'

interface ClientEvents { hello: () => void; }
interface ServerEvents { basicEmit: (a: number, b: string) => void; }
interface InterEvents { ping: () => void; }
interface SocketData { user: { id: string, role: string }; }

const fastify = Fastify()

// Fastify automatically infers the types for fastify.io!
fastify.register(fastifySocketIO<
  ClientEvents,
  ServerEvents,
  InterEvents,
  SocketData
>)

// Connect to the live production server
import { io } from "socket.io-client";

const socket = io("https://fastify-socket-io.onrender.com", {
  // Pass your JWT token if the route requires authentication
  auth: {
    token: "your-jwt-token"
  }
});

socket.on("connect", () => {
  console.log("Successfully connected to the live Render server!");
});
